@Bean
MessageStore store(DataSource ds) {
    JdbcMessageStore s = new JdbcMessageStore(ds);   // packaged schema: int_message, int_group
    s.setRegion("orders.audit");                     // one region per audit stream
    return s;
}
@Bean
IntegrationFlow flow(MessageStore store) {
    return IntegrationFlow.from("orders")
        .wireTap(t -> t.handle(m -> store.addMessage(m)))   // copy, off the main path
        .handle(orderService())                             // business handling unchanged
        .get();
}

