try (Connection c = ds.getConnection()) {
    c.setAutoCommit(false);                        // one transaction per batch
    try (PreparedStatement ps = c.prepareStatement(
            "INSERT INTO msg_store(id, chan, ts, body) VALUES (?,?,?,?)")) {
        for (StoredMessage m : batch) {
            ps.setString(1, m.id()); ps.setString(2, m.channel());
            ps.setLong(3, m.recordedAt()); ps.setString(4, m.body());
            ps.addBatch();
        }
        ps.executeBatch();                         // one fsync per batch, not per message
        c.commit();
    }
}
